for id,fields in pairs(npcs) do local npc=HP.npcData[id] or {};for k,v in pairs(fields) do npc[k]=v end;HP.npcData[id]=npc end
for id,fields in pairs(facts) do
 local q=HP.questData[id]
 if q then
  for k,v in pairs(fields) do q[k]=v end
  q.races=nil;q.zoneID=16593;q.zone='Zephras Isle';q.classQuest=#q.classes>0 or nil
  if #q.classes==0 then q.classes=nil end
  q.skyborneReviewed=true;q.prerequisitesUnverified=nil
  for _,phase in ipairs({'start','finish'}) do local npc=HP.npcData[q[phase]]
   if npc then q[phase..'Name']=npc.name;if not fields[phase..'Location'] and npc.location then q[phase..'Location']=npc.location end end
  end
  if q.startLocation or q.startItem or q.startObject then q.navigationPending=false end
 end
